//! Файл: settings/catalog/dex.rs
//! Что делает: настройки адаптера DEX — узел BSC, режим обмена, пулы, проверка расчёта, разрешения,
//! умный режим и адреса контрактов каждого вида пула. Значений нет.
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, решения 29, 31, 38).
//! Решение 283: у настроек области «площадка» здесь — .dex_venue() (значение читается только у площадки DEX; интерфейс
//! не показывает их на экране биржи). Чтение и запись это не меняет.
//! Решение 435 (433-ж): настройки узла bsc.* — области «вся система + площадка» (GV): значение площадки DEX сильнее
//! общего; у bsc_dex без своего значения действует прежнее общее (живые настройки BSC не переносятся), у arb_dex —
//! своё (узел Arbitrum).
//!
//! Адреса контрактов — только из официальной документации DEX (research/flow/bsc_dex.md, bsc_v4.md,
//! bsc_smart_router.md); вводит Тигран. Область «DEX» (dx): id — id DEX у индексатора (решение 58, таблица
//! сопоставления dex.kind), например «pancakeswap-v3-bsc».

use super::{DX, G, GV, V, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Решение 463 (четвёртое ревью t236): предел dex.fusion_fee_horizon_s, секунды — secondsAgo = WINDOW + горизонт + 1
/// (uint32 в getTimepoints оператора AlgebraV1; WINDOW = DataStorage 1 days = 86400). Каталог не зависит от адаптера (как
/// SBE_SNAPSHOT_LIMIT_MAX у binance.rs); код берёт предел отсюда, а venues/bsc_dex/math/fee_algebra_v1.rs сверяет его с
/// WINDOW при сборке (const assert).
pub const FUSION_HORIZON_MAX: u64 = u32::MAX as u64 - 86_400 - 1;

